const incoming = $input.first().json;
let data = incoming.body ?? incoming;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch { throw new Error('Request body must be valid JSON'); }
}
const clean = value => String(value ?? '').trim();
const escapeHtml = value => clean(value).replace(/[&<>\"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const name = clean(data.name).slice(0, 100);
const email = clean(data.email).slice(0, 254).toLowerCase();
const phone = clean(data.phone).slice(0, 25);
const service = clean(data.service).slice(0, 100);
const date = clean(data.date).slice(0, 10);
const time = clean(data.time).slice(0, 60);
const note = clean(data.message).slice(0, 500);
if (clean(data.company)) throw new Error('Invalid form submission');
if (!name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !phone || !/^\d{4}-\d{2}-\d{2}$/.test(date) || !service || !time) {
  throw new Error('Please provide a valid name, email, phone, service, date, and time');
}
const safeName = escapeHtml(name);
const safeEmail = escapeHtml(email);
const safePhone = escapeHtml(phone);
const safeService = escapeHtml(service);
const safeDate = escapeHtml(date);
const safeTime = escapeHtml(time);
const safeNote = escapeHtml(note).replace(/\r?\n/g, '<br>') || 'No additional note';
const details = `<table role="presentation" style="width:100%;border-collapse:collapse"><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Name</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeName}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Email</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeEmail}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Phone</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safePhone}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Requested service</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeService}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Preferred date</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeDate}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Preferred time</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeTime}</td></tr><tr><td style="padding:10px"><b>Note</b></td><td style="padding:10px">${safeNote}</td></tr></table>`;
const siteUrl = 'https://dentora-clinic-02.vercel.app/';
const siteUrl = 'https://dentora-clinic-02.vercel.app/';
const shell = body => {
  const logoUrl = siteUrl + 'assets/favicon.svg';
  return '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#f3f4f3" style="width:100%;background:#f3f4f3;padding:28px 12px;font-family:Arial,Helvetica,sans-serif;color:#202727"><tr><td align="center">' +
    '<table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:600px;border-collapse:separate;border-spacing:0;background:#fff;border-radius:16px;overflow:hidden">' +
    '<tr><td bgcolor="#21484b" style="background:#21484b;padding:25px 30px 22px"><a href="' + siteUrl + '" style="display:inline-block;color:#fff;text-decoration:none"><img src="' + logoUrl + '" width="38" height="38" alt="Dentora tooth logo" style="display:inline-block;width:38px;height:38px;vertical-align:middle;border:0;margin-right:10px"><span style="font-size:25px;font-weight:700;letter-spacing:-1px;vertical-align:middle;color:#fff">Dentora</span><span style="font-size:11px;color:#d5e8e6;vertical-align:top">&reg;</span></a><div style="margin-top:10px;color:#c7ddda;font-size:11px;letter-spacing:1.2px;text-transform:uppercase">Dentistry with a personal touch</div></td></tr>' +
    '<tr><td style="padding:30px 30px 28px;background:#fff;font-size:15px;line-height:1.65;color:#344241">' + body + '</td></tr>' +
    '<tr><td bgcolor="#e8f0ee" style="background:#e8f0ee;padding:22px 30px 24px;border-top:1px solid #dce7e4"><div style="color:#21484b;font-size:13px;font-weight:700">Dentora Dental Care</div><div style="margin-top:5px;color:#62716e;font-size:12px;line-height:1.6">Clear advice. Care at your pace.</div><div style="margin-top:16px"><a href="' + siteUrl + '" style="display:inline-block;margin:0 16px 6px 0;color:#237e86;font-size:12px;font-weight:700;text-decoration:none"><span style="display:inline-block;margin-right:5px;color:#21484b">&#8599;</span>Visit website</a><a href="mailto:ar0207493@gmail.com" style="display:inline-block;margin-bottom:6px;color:#237e86;font-size:12px;font-weight:700;text-decoration:none"><span style="display:inline-block;margin-right:5px;color:#21484b">&#9993;</span>Email the clinic</a></div><div style="margin-top:12px;color:#82908d;font-size:10px">Please reply to this email if you have any questions.</div></td></tr>' +
    '</table></td></tr></table>';
};
const adminHtml = shell(`<h2 style="font-size:21px">New appointment request</h2><p>A patient has sent an appointment request. Please contact them to confirm availability.</p>${details}`);
const patientHtml = shell(`<h2 style="font-size:21px">We received your request, ${safeName}.</h2><p>Thank you for contacting Dentora. Your appointment request is with our team. This email confirms receipt only; your appointment is not booked until the clinic confirms a time with you.</p><h3 style="font-size:16px">Your requested visit</h3>${details}<p>Our team will follow up using the contact details you provided.</p>`);

const makeRawEmail = (to, subject, html) => {
  const encodedSubject = Buffer.from(subject.replace(/[\r\n]+/g, ' '), 'utf8').toString('base64');
  const encodedBody = Buffer.from(html, 'utf8').toString('base64').match(/.{1,76}/g).join('\r\n');
  const mime = [
    'From: Dentora Dental Care <ar0207493@gmail.com>',
    'To: ' + to,
    'Subject: =?UTF-8?B?' + encodedSubject + '?=',
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
    '', encodedBody
  ].join('\r\n');
  return Buffer.from(mime, 'utf8').toString('base64url');
};
const adminRaw = makeRawEmail('ar0207493@gmail.com', 'New appointment request — ' + name, adminHtml);
const patientRaw = makeRawEmail(email, 'We received your appointment request | Dentora', patientHtml);
return [{ json: { name, email, phone, service, date, time, message: note, adminHtml, patientHtml, adminRaw, patientRaw } }];
